// :id est un paramètre de chemin.
app.get("/api/livres/:id", (req, res) => {
  const id = Number(req.params.id);
  // Les valeurs de query sont toujours des chaînes au départ.
  const details = req.query.details === "true";
  res.json({ id, details });
});

app.post("/api/livres", (req, res) => {
  // express.json() doit être déclaré avant cette route.
  res.status(201).json(req.body);
});
